'use strict';
/* Public experience and device-first drafts. No provider credentials or answer bodies. */
window.PrepPilotUI = (() => {
  const catalogue=window.PILOT_CATALOGUE||[], byId=new Map(catalogue.map(p=>[p.id,p]));
  const formatNames={implementation:'Implementation',debugging:'Debugging',testing:'Test design',project:'Multi-file project'};
  const terminal=new Set(['completed','incorrect_output','compile_error','runtime_error','timeout','output_limit','stopped','infrastructure_error']);
  let connection=null,connectionPromise=null,active=null,lastResults=new Map(),answerCache=new Map(),saving=new Map(),saveTimers=new Map();
  let mounted=null,pendingDeletion=false;
  const dateOnly=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
  const dueDate=(date,days)=>new Date(Date.parse(date+'T12:00:00Z')+days*86400000).toISOString().slice(0,10);
  function problem(item){return item?.language==='java'?byId.get(item.id):null;}
  function initialize(){state.pilotDrafts??={};state.pilotAssistance??={};state.pilotDays??={};state.pilotResults??={};}
  async function api(path,options={}){
    const response=await fetch('/api/pilot/'+path,{credentials:'same-origin',cache:'no-store',...options,headers:{'Content-Type':'application/json',...(state.pilotWorkspaceKey?{'X-PrepSpace-Workspace':state.pilotWorkspaceKey}:{}),...options.headers}});
    let body;try{body=await response.json();}catch{throw new Error('The preparation service is unavailable. Your browser draft is preserved.');}
    if(!response.ok){const error=new Error(body.error||'The request could not be completed.');error.status=response.status;error.body=body;if(body.code==='workspace_changed'){error.status=401;error.accountChanged=true;connection=null;connectionPromise=null;setTimeout(()=>render(),0);}throw error;}
    return body;
  }
  async function health(force=false){if(force)connectionPromise=null;if(!connectionPromise)connectionPromise=api('state').then(value=>{scopeWorkspace(value);return connection=value;}).catch(error=>{connection={mode:'offline',executionReady:false,cloudSync:false,error:error.message};return connection;});return connectionPromise;}
  function scopeWorkspace(profile){const key=profile.workspaceKey||'anonymous',old=state.pilotWorkspaceKey,fields=['pilotDrafts','pilotAssistance','pilotPlan','pilotPlanRevision','pilotPlanDirty','pilotPlanConflict','pilotPlanBackup','pilotResults','pilotSummaryAttempts','learningJourney','journeyReflections','journeyReadiness','javaTutorialChecks','javaTutorialProgress'];if(old&&old!==key){const stash=Object.fromEntries(fields.map(field=>[field,state[field]]));try{localStorage.setItem('prepspace-workspace::'+old,JSON.stringify(stash));}catch{}let restored={};try{restored=JSON.parse(localStorage.getItem('prepspace-workspace::'+key)||'{}');}catch{}for(const field of fields){delete state[field];if(restored[field]!==undefined)state[field]=restored[field];}lastResults.clear();answerCache.clear();}state.pilotWorkspaceKey=key;state.pilotWorkspaceKind=profile.mode;initialize();persist();}
  function link(p,label='Practise'){return `<a class="button small" href="#/lab?round=coding&domain=Investment+Banking&language=java&question=${encodeURIComponent(p.id)}">${esc(label)} ↗</a>`;}
  function assurance(p){return `<span class="coverage-tag ${p.verification.status==='verified'?'verified':'pending'}">${p.verification.status==='verified'?'Automated checks verified':'Verification pending'}</span><span class="coverage-tag">Java 17 · v${p.version}</span><span class="coverage-tag">Practitioner review pending</span>`;}
  function prompt(p){return `<div class="question-topics"><span class="difficulty difficulty-${p.difficulty.toLowerCase()}">${p.difficulty}</span><span class="question-topic">${formatNames[p.format]}</span><span class="question-topic">${esc(p.competency.replaceAll('-',' '))}</span></div><p class="problem-statement">${esc(p.description)}</p><div class="contract-box"><strong>Input and output contract</strong><p>${esc(p.contract)}</p></div>${p.examples.map((example,n)=>`<section class="question-example"><h3>Example ${n+1}: ${esc(example.name)}</h3><div class="example-values"><div><strong>${p.format==='testing'?'Case input':'Input'}</strong><pre>${esc(example.input||'(no standard input)')}</pre></div><div><strong>${p.format==='testing'?'Expected result for this case':'Output'}</strong><pre>${esc(example.expected)}</pre></div></div></section>`).join('')}<section class="question-constraints"><h3>Constraints</h3><ul>${p.constraints.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><p class="question-follow-up"><strong>Interview follow-up:</strong> ${esc(p.followup)}</p><div class="pilot-facts">${assurance(p)}</div><p class="pilot-meta">Updated ${p.review.updated} · Content owner: ${esc(p.review.owner)}. Verification covers the reference implementation and a rejected negative control. External practitioner review is pending.</p>`;}
  function draft(p){initialize();if(!state.pilotDrafts[p.id])state.pilotDrafts[p.id]={files:{...p.starter},activeFile:'Main.java',revision:0,explanation:'',snapshots:[],updatedAt:null};return state.pilotDrafts[p.id];}
  function assistance(p){initialize();return state.pilotAssistance[p.id]??={hints:0,answerViewed:false,solutionLoaded:false,externalHelp:false};}
  function snapshot(p){const d=draft(p);d.snapshots=[{files:{...d.files},at:new Date().toISOString()},...(d.snapshots||[])].slice(0,3);}
  function saveLabel(text,error=false){const label=document.getElementById('pilot-save-status');if(label){label.textContent=text;label.dataset.save=error?'error':'saved';}}
  function saveDraft(p,code){const d=draft(p);if(code!==undefined)d.files[d.activeFile]=code;d.updatedAt=new Date().toISOString();d.dirty=true;const ok=persist();d.localSaveOk=ok;saveLabel(ok?'Saved in this browser · syncing to preparation service…':'Browser storage is full or unavailable. Download your code now.',!ok);clearTimeout(saveTimers.get(p.id));saveTimers.set(p.id,setTimeout(()=>syncDraft(p),600));return ok;}
  async function syncDraft(p){const d=draft(p);if(saving.get(p.id)){d.dirty=true;return;}saving.set(p.id,true);d.dirty=false;const sent=JSON.stringify(d.files);try{const result=await api('drafts',{method:'POST',body:JSON.stringify({problemId:p.id,language:'java',revision:d.revision,files:d.files})});d.revision=result.revision;d.conflict=null;persist();if(mounted===p.id)saveLabel(d.localSaveOk===false?'Saved to the service · browser storage unavailable':connection?.mode==='hosted'?'Saved in this browser and your account':'Saved in this browser and this Mac');}catch(error){if(error.status===409){d.conflict=error.body;persist();paintConflict(p);}else if(mounted===p.id)saveLabel('Saved in this browser · server sync unavailable',false);}finally{saving.delete(p.id);if(d.dirty||sent!==JSON.stringify(d.files))clearTimeout(saveTimers.get(p.id)),saveTimers.set(p.id,setTimeout(()=>syncDraft(p),800));}}
  function paintConflict(p){const el=document.getElementById('pilot-draft-conflict');if(el){el.hidden=!draft(p).conflict;el.innerHTML=draft(p).conflict?'<p>A different saved draft exists. Both copies are preserved. Choose which one to continue.</p><button class="button small" data-conflict="server">Use saved server copy</button> <button class="button small" data-conflict="local">Keep this browser copy</button>':'';}saveLabel('Draft conflict · choose which copy to continue',true);}
  function files(p,code){const d=draft(p);if(code!==undefined)d.files[d.activeFile]=code;return {...d.files};}
  function home(){const verified=catalogue.filter(p=>p.verification.status==='verified').length;return `<section class="public-hero pilot-hero"><div class="hero-message"><span class="public-eyebrow"><i></i> BANKING JAVA & SDET · FREE PILOT</span><h1>Prepare for the work.<br><em>Explain your thinking.</em></h1><p>Build confidence for banking engineering interviews. Solve realistic Java problems, inspect the test evidence and practise explaining the decisions behind your code.</p><div class="hero-actions"><a class="button primary large" href="#/prepare">Build a preparation plan <span>→</span></a><a class="button large" href="#/lab?round=coding&domain=Investment+Banking&language=java">Try a banking problem <span>↗</span></a></div><div class="hero-trust"><span>${verified} verified Java exercises</span><i></i><span>2 specialist role paths</span><i></i><span>5 interview rounds</span></div><p class="pilot-availability">Free to explore. Java backend and QA/SDET paths available. Wider domains and languages remain available as clearly labelled preparation material.</p></div><aside class="preview-interview pilot-preview"><div class="preview-label"><span class="live-dot"></span> FROM PRACTICE TO EVIDENCE <span>JAVA / BANKING</span></div><div class="preview-question"><span class="pill">Reconciliation · Live coding</span><h2>Which trades are missing?</h2><p>Clarify the contract. Preserve the expected order.</p><pre>Expected  T1, T2, T3, T4\nActual    T2, T4, T5\n\nResult    T1, T3</pre></div><div class="answer-outline"><span>WHAT YOU WILL PRACTISE</span><div><b>01</b><p><strong>Implement and test</strong><small>Normal cases, ordering and boundary conditions.</small></p></div><div><b>02</b><p><strong>Explain the decision</strong><small>Collections, complexity and business assumptions.</small></p></div><div><b>03</b><p><strong>Try a fresh variation</strong><small>Revisit the competency in another scenario.</small></p></div></div><a href="#/lab?round=coding&domain=Investment+Banking&language=java&question=2-06-find-trades-missing-from-actual-results" class="preview-action">Practise this scenario <span>→</span></a></aside></section><section class="explore-entry"><div class="section-intro"><span class="public-eyebrow">PRACTICAL PREPARATION, WITH A CLEAR PATH</span><h2>Choose the role. Build the evidence.</h2><p>Start with a focused banking path or explore the broader preparation library.</p></div><div class="pilot-cards">${trackCards()}</div><div class="entry-grid"><a class="entry-card" href="#/domains"><span class="entry-icon">◈</span><h3>Explore domains</h3><p>See the preparation and assessed coding coverage available for each industry.</p><span>Check availability →</span></a><a class="entry-card" href="#/languages"><span class="entry-icon mono">{ }</span><h3>Explore languages</h3><p>Java assessment first, with existing Python, JavaScript and TypeScript study material.</p><span>Choose a language →</span></a><a class="entry-card" href="#/evidence"><span class="entry-icon">◎</span><h3>Review your evidence</h3><p>See attempts, assistance recorded and the competencies to revisit. Every result has context.</p><span>Open progress evidence →</span></a></div></section><section class="pilot-section"><div class="section-intro"><span class="public-eyebrow">A PRACTICE CYCLE THAT MAKES SENSE</span><h2>Understand it. Try it. Explain it. Revisit it.</h2></div><div class="pilot-journey">${[['Diagnose','Start with a representative task and identify what needs work.'],['Learn','Read the concept and its input/output scenario.'],['Attempt','Write code, debug a defect or design tests.'],['Inspect','Compare actual results with the documented contract.'],['Explain','Connect your implementation to domain decisions.'],['Transfer','Try a different task after several days.']].map(([name,text],i)=>`<div class="pilot-step"><b>0${i+1}</b><h3>${name}</h3><p>${text}</p></div>`).join('')}</div></section><section class="round-section"><div class="section-intro"><span class="public-eyebrow">THE COMPLETE INTERVIEW JOURNEY</span><h2>Prepare beyond the code.</h2><p>Use the introduction, technical, manager and HR rounds to practise truthful examples and explain the decisions that matter.</p></div>${roundCards()}</section><section class="bottom-cta"><div><h2>One useful session starts here.</h2><p>Pick a task. Keep your draft. Let the evidence guide your next step.</p></div><a class="button primary large" href="#/prepare">Start preparing →</a></section>`;}
  function concept(p){const id=({'collections':'1-04-collections-lists-sets-queues-and-copies','aggregation':'1-07-collectors-grouping-and-financial-reductions','financial-precision':'1-03-bigdecimal-financial-arithmetic-and-rounding','validation':'1-01-objects-constructors-and-immutability','reconciliation':'1-04-collections-lists-sets-queues-and-copies','ranking':'1-05-maps-sorted-maps-and-comparators','ordered-collections':'1-05-maps-sorted-maps-and-comparators','idempotency':'1-09-atomic-updates-concurrent-maps-and-bounded-queues','concurrency':'1-08-threads-executors-futures-and-lifecycle-management','retry-policy':'cloud-reliability','api-contracts':'data-quality'})[p.competency]||'coding-concept';return `<a class="button small" href="#/lesson/${id}?language=java">Study the concept ↗</a>`;}
  function trackCards(){return [['backend','Java / Backend Engineer','Collections, financial precision, reconciliation, idempotency and bounded concurrency.'],['sdet','QA / SDET','API contracts, diagnostic debugging, boundary tests, fault detection and regression execution.']].map(([id,title,text])=>`<article class="pilot-card"><span class="public-eyebrow">BANKING ROLE PATH</span><h2>${title}</h2><p>${text}</p><div class="pilot-facts"><span>7, 14 or 28 days</span><span>Java 17</span><span>Five interview rounds</span></div><a class="button primary" href="#/prepare?track=${id}">Prepare for this role →</a></article>`).join('');}
  function controls(questions,item){const r=route(),format=r.query.get('format')||'all';return `<div class="lab-controls coding-controls"><div><label for="lab-domain">DOMAIN</label><select id="lab-domain" aria-label="Practice domain">${['All domains',...domains].map(d=>`<option value="${esc(d)}" ${currentDomain===d?'selected':''}>${esc(d)}</option>`).join('')}</select></div><div><label for="lab-language">SOLUTION LANGUAGE</label><select id="lab-language">${Object.entries(languageConfig).map(([id,c])=>`<option value="${id}" ${id===currentLanguage?'selected':''}>${c.name}</option>`).join('')}</select></div><div><label for="pilot-format">PRACTICE FORMAT</label><select id="pilot-format"><option value="all">All coding formats</option>${Object.entries(formatNames).map(([id,name])=>`<option value="${id}" ${format===id?'selected':''}>${name}</option>`).join('')}</select></div><div><label for="lab-question">PRACTICE QUESTION</label><select id="lab-question" ${questions.length?'':'disabled'}>${questions.length?questions.map(i=>`<option value="${i.id}" ${item?.id===i.id?'selected':''}>${esc(i.title)}${problem(i)?' · assessed':''}</option>`).join(''):'<option>No problems for these filters</option>'}</select></div></div><p class="pilot-availability">${questions.length} matching coding problems · ${questions.filter(i=>problem(i)).length} with automated Java checks. Domain filters match exact tags. Shared exercises appear under All domains.</p>`;}
  function lab(){const {questions,item,round}=labQuestion(),p=problem(item);if(!p)return null;if(!connection||connection.mode==='offline'&&state.pilotWorkspaceKind==='hosted')return heading('Practice','Checking your private workspace before loading saved code.')+controls(questions,item)+`<p class="pilot-notice">${connection?.mode==='offline'?'Reconnect to verify your account. Cached work remains on this device.':'Loading your workspace…'}</p>`;const d=draft(p),a=assistance(p);return `<div class="pilot-lab">${heading('Practice','Work through a realistic coding task. Inspect the evidence, explain your decisions and reveal the answer when you choose.')}${controls(questions,item)}<details class="pilot-walkthrough"><summary>First time here? Take a quick environment walkthrough</summary><ol><li>Read the contract and examples. The supplied entry point handles terminal input.</li><li>Choose a file tab for multi-file projects. Drafts save in this browser and sync when the service is available.</li><li>Run samples first, then check the full contract. Expected and actual results stay separate from self-review.</li><li>Request hints when useful. Show answer reveals the worked solution; loading it is a separate action.</li><li>Write a short explanation. Use your evidence and a later variation to guide your next session.</li></ol><p class="pilot-muted">This is representative interview practice. Actual employers choose their own formats and assessment settings.</p></details><div class="lab-grid"><section class="lab-work"><article class="lab-prompt reading-body"><span class="pill">Live Coding Round · Investment Banking · Java</span><h2>${esc(p.title)}</h2>${prompt(p)}${concept(p)}</article><section class="practice-hints" data-pilot-hints><div class="hint-heading"><h3>Need a hint?</h3><span data-pilot-hint-count>0 of ${p.hints.length}</span></div><p>Try independently first. Requesting a hint is recorded with your next attempt.</p><ol data-pilot-hint-list></ol><button class="button small" data-pilot-next-hint>Show first hint</button></section><div class="lab-editor"><div class="pad-heading"><h3>Your Java solution</h3><span>Java 17 · ${formatNames[p.format]}</span></div><div class="pilot-editor-status" id="pilot-save-status">${d.updatedAt?'Browser draft restored':'Starter ready · changes save automatically'}</div>${(state.drafts[p.id+'::java']||state.drafts[p.id])&&!d.legacyHandled?'<div class="pilot-notice"><p>An earlier Java draft uses the previous manual interface. It is preserved; adapt it to this version’s terminal contract when restoring.</p><button class="button small" data-legacy-draft>Restore earlier Java draft</button></div>':''}<div id="pilot-draft-conflict" class="pilot-notice" hidden></div><div class="pilot-file-tabs" role="tablist" aria-label="Project files">${Object.keys(d.files).map(name=>`<button type="button" role="tab" aria-selected="${name===d.activeFile}" data-pilot-file="${esc(name)}">${esc(name)}</button>`).join('')}</div><label class="sr-only" for="lab-answer">Java source file</label><textarea id="lab-answer" spellcheck="false">${esc(d.files[d.activeFile])}</textarea>${compilerPanel(item)}<div class="pilot-actions"><button class="button primary" data-pilot-check>Check full contract</button><button class="button small" data-pilot-restore>Restore previous project</button><button class="button small" data-pilot-download>Download project</button></div><p class="pilot-muted" data-pilot-quota>Checking execution availability…</p></div><section id="pilot-result" class="pilot-results" aria-live="polite"><h3>Test evidence</h3><p class="pilot-muted">Run samples or check the full contract to inspect actual results. Tests do not automatically grade your explanation or certify production readiness.</p></section><section class="pilot-explanation"><h3>Explain your decisions</h3><label for="pilot-explanation">What did you assume? Why this design? Which tests and production risks matter? Your explanation is saved with the next attempt.</label><textarea id="pilot-explanation" placeholder="Assumptions and approach…\nTests and edge cases…\nComplexity, trade-offs and banking risks…">${esc(d.explanation||'')}</textarea><label style="margin-top:12px"><input type="checkbox" id="pilot-external-help" ${a.externalHelp?'checked':''}> I used external assistance for this problem</label><p class="pilot-muted">Assistance is a browser record and self-report, rather than a proctored claim. Explanations are self-reviewed.</p></section><section class="practice-answer pilot-answer"><p>Ready to compare your approach?</p><button class="button" data-pilot-answer aria-expanded="false" aria-controls="pilot-answer-body">Show answer</button><div id="pilot-answer-body" hidden></div></section></section><aside class="lab-checks"><span class="public-eyebrow">REFLECT, THEN REFINE</span><h2>Answer self-check</h2><p>Review the reasoning behind your code. These tick marks are prompts, separate from automated test results.</p><ul class="lab-criteria">${round.rubric.map(x=>`<li><span class="criteria-tick" aria-hidden="true">✓</span><span>${esc(x)}</span></li>`).join('')}</ul><a class="text-link" href="#/evidence">Review attempt evidence ↗</a><p class="pilot-muted" data-pilot-assistance>${assistanceLabel(a)}</p><details class="pilot-report"><summary>Report a problem with this exercise</summary><form id="pilot-report-form"><label class="sr-only" for="pilot-report-kind">Issue type</label><select id="pilot-report-kind"><option value="content">Question or explanation</option><option value="tests">Test expectations</option><option value="accessibility">Accessibility</option><option value="feedback">Feedback quality</option></select><label class="sr-only" for="pilot-report-body">Issue details</label><textarea id="pilot-report-body" minlength="5" maxlength="2000" required placeholder="Describe the issue and a reproducible example. Do not include private employer data."></textarea><button class="button small">Record issue</button><p class="pilot-muted" id="pilot-report-status"></p></form></details><div class="pilot-report"><strong style="font-size:12px">Free pilot</strong><p class="pilot-muted">20 execution jobs per day, subject to the shared capacity allocation. No payment details required.</p><a class="text-link" href="#/pilot">Privacy, limits & account ↗</a></div></aside></div></div>`;}
  function assistanceLabel(a){const bits=[];if(a.hints)bits.push(a.hints+' hint(s) seen');if(a.answerViewed)bits.push('answer viewed');if(a.solutionLoaded)bits.push('worked solution loaded');if(a.externalHelp)bits.push('external help reported');return bits.length?'Assistance recorded: '+bits.join(' · '):'No assistance recorded for this problem in this browser.';}
  function markAssistance(p){persist();const el=document.querySelector('[data-pilot-assistance]');if(el)el.textContent=assistanceLabel(assistance(p));}
  function resultHtml(attempt){const result=attempt.result;if(!result)return `<h3>${attempt.status==='queued'?'Queued for execution':'Checking your solution'}</h3><p role="status">${attempt.status==='queued'?'Your source is saved. Waiting for a bounded execution slot.':'Compiling and running the documented-contract checks…'}</p>`;const titles={completed:'Checks passed',incorrect_output:'Inspect the failing checks',compile_error:'Fix the compilation diagnostic',runtime_error:'Inspect the runtime diagnostic',timeout:'Execution time limit reached',output_limit:'Output limit reached',stopped:'Run stopped',infrastructure_error:'Execution service interrupted'};return `<div class="result-summary"><h3>${titles[result.status]||'Execution result'}</h3><span class="coverage-tag ${result.status==='completed'?'verified':'pending'}">${attempt.mode==='samples'?'Samples':'Full check'}${result.total?' · '+result.passed+'/'+result.total:''}</span></div><p class="pilot-muted">${esc(result.diagnostic||'')}${result.durationMs?' · '+result.durationMs+' ms':''}</p>${result.cases?.map(c=>`<details class="result-case" ${c.passed?'':'open'}><summary><span class="${c.passed?'case-pass':'case-fail'}">${c.passed?'✓':'×'}</span>${esc(c.name)}<span class="coverage-tag">${esc(c.category||'contract')}</span></summary>${c.input!==undefined&&c.input!==null?`<label>Reproducible input</label><pre>${esc(c.input||'(empty input)')}</pre>`:''}<label>Expected</label><pre>${esc(c.expected??c.diagnostic??'Valid assertion')}</pre><label>Actual</label><pre>${esc(c.actual??c.diagnostic??'Invalid assertion')}</pre></details>`).join('')||''}${['compile_error','runtime_error','timeout','infrastructure_error'].includes(result.status)?`<pre class="pilot-diagnostic">${esc(result.diagnostic||'No additional diagnostic.')}</pre>`:''}${result.feedback?`<div class="pilot-feedback"><h4>Evidence-based feedback</h4><ul>${result.feedback.observations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="pilot-muted">${esc(result.feedback.limitations)}</p></div>`:''}<p class="pilot-muted">Assistance: ${esc(assistanceLabel(attempt.assistance||{}))} <a href="#/evidence">View history →</a></p>`;}
  function paintRun(attempt){const el=document.getElementById('pilot-result');if(el)el.innerHTML=resultHtml(attempt);document.getElementById('run-code')?.toggleAttribute('disabled',!!active);document.getElementById('stop-code')?.toggleAttribute('disabled',!active);document.querySelector('[data-pilot-check]')?.toggleAttribute('disabled',!!active);}
  async function execute(mode='samples'){
    const profile=await health();if(!profile.executionReady){toast(profile.mode==='hosted'?'Sign in and join the invited pilot, or check execution setup on the pilot page.':'Execution is unavailable. Your browser draft is preserved.');return;}
    const item=labQuestion().item,p=problem(item);if(!p||active)return;saveDraft(p,PrepEditor.getValue());snapshot(p);persist();
    const record={id:crypto.randomUUID(),problemId:p.id,controller:new AbortController()};active=record;let attempt={id:record.id,mode,status:'queued',assistance:{...assistance(p)}};paintRun(attempt);
    try{await api('evaluate',{method:'POST',body:JSON.stringify({runId:record.id,problemId:p.id,version:p.version,mode,files:files(p),assistance:assistance(p),explanation:draft(p).explanation||''}),signal:record.controller.signal});
      while(active===record){attempt=await api('jobs/'+record.id,{signal:record.controller.signal});if(active!==record)break;paintRun(attempt);if(terminal.has(attempt.status)){api('events',{method:'POST',body:JSON.stringify({kind:'result_viewed',attemptId:attempt.id})}).catch(()=>{});lastResults.set(p.id,attempt);state.pilotResults[p.id]=attempt.id;persist();break;}await new Promise(resolve=>setTimeout(resolve,900));}
    }catch(error){if(active===record){const interrupted={...attempt,result:{status:'infrastructure_error',diagnostic:error.message,cases:[],passed:0,total:0}};lastResults.set(p.id,interrupted);paintRun(interrupted);}}
    finally{if(active===record){active=null;paintRun(lastResults.get(p.id)||attempt);await health(true);paintConnection();}}
  }
  function stop(){if(!active)return false;const record=active;active=null;record.controller.abort();fetch('/api/pilot/jobs/'+record.id+'/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}',keepalive:true}).catch(()=>{});const attempt={id:record.id,mode:'check',assistance:{...assistance(byId.get(record.problemId))},result:{status:'stopped',cases:[],total:0,passed:0,diagnostic:'You stopped this run. Your source is preserved.'}};lastResults.set(record.problemId,attempt);paintRun(attempt);return true;}
  function paintConnection(){document.querySelectorAll('[data-pilot-quota]').forEach(el=>{el.textContent=connection?.executionReady?`${connection.quota.remaining} of ${connection.quota.limit} daily jobs remaining · resets ${new Date(connection.quota.resetAt).toLocaleString()} · ${connection.mode==='local'?'Runs on this Mac':'Private isolated cloud execution'}`:connection?.error||'Hosted execution is not configured. Your draft, reading material and downloads remain available.';});}
  async function reveal(p,button){const body=document.getElementById('pilot-answer-body');if(button.getAttribute('aria-expanded')==='true'){button.setAttribute('aria-expanded','false');button.textContent='Show answer';body.replaceChildren();body.hidden=true;return;}button.disabled=true;button.textContent='Loading answer…';try{const answer=answerCache.get(p.id)||await api('problems/'+p.id+'/answer');answerCache.set(p.id,answer);if(mounted!==p.id)return;assistance(p).answerViewed=true;markAssistance(p);body.innerHTML=`<div class="answer-content reading-body"><h3>Worked answer & explanation</h3><button class="button small" data-pilot-load-answer>Load worked project into editor</button><ol>${answer.explanation.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${Object.entries(answer.files).map(([name,source])=>`<div class="answer-file"><h4>${esc(name)}</h4><pre><code>${esc(source)}</code></pre></div>`).join('')}</div>`;body.hidden=false;button.textContent='Hide answer';button.setAttribute('aria-expanded','true');}catch(error){toast(error.message);button.textContent='Show answer';}finally{button.disabled=false;}}
  function install(){initialize();
    const oldHome=publicHome;publicHome=home;
    const oldLab=labPage;labPage=()=>{const selection=labQuestion();if(!selection.item&&route().query.get('format')&&route().query.get('format')!=='all')return heading('Practice','Find a coding exercise for the domain, language and format you want to practise.')+controls(selection.questions,null)+`<section class="empty"><h2>No coding problems match these filters.</h2><p>The selected format has no exercises in ${esc(currentDomain)} for ${languageConfig[currentLanguage].name}.</p><a class="button" href="#/lab?domain=${encodeURIComponent(currentDomain)}&language=${currentLanguage}">Show all coding formats →</a></section>`;return lab()??(`<div class="pilot-notice">This exercise uses the existing manual practice runner. Automated contract checks are currently available for the banking Java pilot catalogue.</div>`+oldLab());};
    labControls=controls;
    const oldQuestions=labQuestions;labQuestions=(domain=currentDomain)=>{const all=oldQuestions(domain),format=route().query.get('format')||'all';return all.filter(item=>format==='all'||(problem(item)?.format||'implementation')===format);};
    const oldDomains=domainsPage;domainsPage=()=>heading('Prepare by domain.','Explore available preparation material and check assessed coding coverage before you begin.')+`<div class="domain-catalog">${domains.map((name,n)=>{const count=baseData.filter(p=>p.type==='problem'&&p.category!=='Parsing archive'&&p.language==='java'&&p.domain===name).length,verified=catalogue.filter(p=>p.domain===name&&p.verification.status==='verified').length;return `<article class="catalog-card"><span class="catalog-number">0${n+1} / ${['IB','CB','EC','AI','CL','DE'][n]}</span><h2>${esc(name)}</h2><p>${esc(domainDescriptions[name])}</p><div class="pilot-facts"><span>${count} Java coding problems</span><span class="coverage-tag ${verified?'verified':'pending'}">${verified} assessed exercises</span></div><p class="pilot-coverage">${verified?'Java/backend and SDET pilot paths available. Practitioner review remains pending.':'Concepts and interview questions are available. Assessed coding coverage is planned; this track is not part of the specialist pilot.'}</p><a class="button" href="#/rounds?domain=${encodeURIComponent(name)}&role=all">Explore preparation →</a>${count?`<a class="button primary" href="#/lab?domain=${encodeURIComponent(name)}&language=java">Open coding lab ↗</a>`:''}</article>`;}).join('')}</div>`;
    const oldLanguages=languagesPage;languagesPage=()=>oldLanguages()+`<section class="pilot-panel" style="margin-top:24px"><h2>Assessment coverage</h2><p class="pilot-muted">Java: ${catalogue.length} banking exercises with automated checks and worked answers. Python, JavaScript and TypeScript: existing study material and manual runners. Verified Java assessment results do not transfer to another language automatically.</p></section>`;
    const oldRoles=rolesPage;rolesPage=()=>heading('Prepare for the role you want.','Start with the banking pilot or explore broader role-specific interview preparation.')+`<div class="pilot-cards">${trackCards()}</div>`+oldRoles().replace(/^<div class="page-heading">[\s\S]*?<\/p><\/div><\/div>/,'');
    planView=prepare;
  }
  function prepare(){if(!connection||connection.mode==='offline'&&state.pilotWorkspaceKind==='hosted')return heading('Build your preparation path.','Connect to verify your private workspace and load its plan.');initialize();const r=route(),existing=state.pilotPlan,track=['backend','sdet'].includes(r.query.get('track'))?r.query.get('track'):existing?.track||'backend',days=existing?.days||14;return heading('Build your preparation path.','A practical banking interview plan with concepts, coding, explanation and a later transfer check.')+`<div id="pilot-plan-conflict" class="pilot-notice" ${state.pilotPlanConflict?'':'hidden'}><p>A different preparation plan is saved on the service. Your browser plan is preserved.</p><button class="button small" data-plan-conflict="server">Use saved server plan</button> <button class="button small" data-plan-conflict="local">Keep browser plan</button></div><form class="pilot-panel" id="pilot-plan-form"><span class="public-eyebrow">BANKING JAVA & SDET · FREE PILOT</span><div class="pilot-form-grid"><label class="pilot-field">ROLE PATH<select id="pilot-plan-track"><option value="backend" ${track==='backend'?'selected':''}>Java / Backend Engineer</option><option value="sdet" ${track==='sdet'?'selected':''}>QA / SDET</option></select></label><label class="pilot-field">PREPARATION WINDOW<select id="pilot-plan-days">${[7,14,28].map(n=>`<option value="${n}" ${n===days?'selected':''}>${n} days</option>`).join('')}</select></label><label class="pilot-field">EXPECTED CODING FORMAT<select id="pilot-plan-format"><option value="mixed">Mixed coding practice</option>${Object.entries(formatNames).map(([id,name])=>`<option value="${id}" ${existing?.format===id?'selected':''}>${name}</option>`).join('')}</select></label></div><button class="button primary">${existing?'Update preparation plan':'Create preparation plan'} →</button><span class="pilot-plan-status" id="pilot-plan-save"></span><p class="pilot-muted">Plan for one focused session of roughly 25–45 minutes. These are representative formats; follow the format confirmed by your recruiter. Updating creates a new schedule while preserving attempts and drafts.</p></form>${existing?planDays(existing):`<section class="pilot-cards">${trackCards()}</section><section class="pilot-walkthrough"><h3>Start with an honest baseline</h3><p class="pilot-muted">Attempt the first problem before requesting hints. Your first full-check result becomes a baseline for that task. It is not a prediction of interview success.</p></section>`}${loops(track)}`;}
  function createPlan(track,days,format){const preferred=track==='sdet'?['testing','debugging','implementation','project']:['implementation','project','debugging','testing'];let pool=[...catalogue].sort((a,b)=>preferred.indexOf(a.format)-preferred.indexOf(b.format));if(format!=='mixed')pool=pool.filter(p=>p.format===format);const tasks=[];let n=0;for(let day=0;day<days;day++){if(day===0){tasks.push({kind:'baseline',problemId:pool[n++%pool.length].id,round:'introduction'});continue;}if(day%7===6){const anchor=byId.get(tasks[Math.max(0,day-6)].problemId),variation=catalogue.find(p=>p.id!==anchor.id&&p.competency===anchor.competency&&!tasks.slice(0,day).some(t=>t.problemId===p.id));tasks.push({kind:'transfer',problemId:(variation||pool[n++%pool.length]).id,round:'manager'});}else tasks.push({kind:'practice',problemId:pool[n++%pool.length].id,round:['technical','coding','technical','hr'][day%4]});}return {track,days,format,startDate:dateOnly(),tasks,completed:[],createdAt:new Date().toISOString()};}
  function planDays(plan){return `<div class="pilot-layout" style="margin-top:24px"><section>${plan.tasks.map((task,n)=>{const p=byId.get(task.problemId);if(!p)return '';const completed=plan.completed.includes(n),due=dueDate(plan.startDate,n);return `<article class="pilot-day" data-completed="${completed}"><span>DAY<b>${n+1}</b>${due}</span><div><span class="coverage-tag">${task.kind==='baseline'?'Baseline attempt':task.kind==='transfer'?'Transfer check':'Focused practice'}</span><h3>${esc(p.title)}</h3><p>${task.kind==='transfer'?'Revisit the competency using another task. Try without hints and compare the assistance recorded.':'Read the contract, attempt the task, inspect failures and write an explanation.'}</p><div>${concept(p)}${link(p,task.kind==='baseline'?'Start baseline':'Open exercise')}<a class="button small" href="#/round/${task.round==='coding'?'technical':task.round}?tab=questions&domain=Investment+Banking">${roundFor(task.round==='coding'?'technical':task.round).short} questions ↗</a></div><button class="pilot-complete" data-pilot-day="${n}" aria-pressed="${completed}">${completed?'✓ Session marked complete':'Mark session complete'}</button></div></article>`;}).join('')}</section><aside class="pilot-panel"><span class="public-eyebrow">YOUR NEXT USEFUL SESSION</span><h2>${plan.days}-day ${plan.track==='sdet'?'SDET':'backend'} plan</h2><p class="pilot-muted">${plan.completed.length} sessions self-marked complete. Completion is separate from automated correctness.</p><ul class="lab-criteria">${['Attempt before revealing the answer','Use failing checks to choose what to revisit','Explain domain assumptions and trade-offs','Try a different task after several days'].map(x=>`<li><span class="criteria-tick">✓</span>${x}</li>`).join('')}</ul><a class="button" href="#/evidence">Review evidence →</a><p class="pilot-muted">Dates are suggestions. Repeat or reschedule a session when useful.</p></aside></div>`;}
  function loops(track){const sdet=track==='sdet';return `<section class="pilot-section"><div class="section-intro"><span class="public-eyebrow">REPRESENTATIVE INTERVIEW SEQUENCE</span><h2>${sdet?'Banking QA / SDET':'Banking Java / Backend'} interview preparation</h2><p>Each round is a separate session. Ordinary coding practice stays untimed.</p></div><section class="pilot-panel">${[
    ['introduction','Introduce your experience',sdet?'Describe an automation contribution, how you measured its effect and what you owned.':'Describe a backend contribution, your responsibilities and a verifiable result.'],
    ['coding','Solve a practical task',sdet?'Debug retry behaviour or design a boundary-focused test suite.':'Reconcile snapshots or implement exact financial aggregation.'],
    ['technical','Explain technical choices',sdet?'Discuss API contracts, test data isolation, parallel execution and diagnostic evidence.':'Explain object identity, decimal arithmetic, collections and safe concurrency.'],
    ['manager','Discuss stakeholder decisions',sdet?'A flaky regression suite threatens a release. Explain risk, evidence and the decision you recommend.':'A replayed trade feed creates reconciliation breaks. Explain containment, recovery and stakeholder communication.'],
    ['hr','Discuss motivation and mutual fit','Use truthful examples to discuss motivation, growth, working style and questions for the team.']].map(([id,title,text],n)=>`<div class="pilot-loop"><span class="public-eyebrow">0${n+1} · ${roundFor(id).name}</span><h3>${title}</h3><p>${text}</p>${id==='coding'?link(byId.get(sdet?'banking-debug-retry-budget':'banking-project-reconciler'),'Open coding task'):`<a class="button small" href="#/round/${id}?tab=questions&domain=Investment+Banking&role=${sdet?'qa-sdet':'software-engineer'}">Prepare this round ↗</a>`}</div>`).join('')}</section></section>`;}
  function evidence(){return heading('Progress, with evidence.','Review what you attempted, what the checks observed and what assistance was recorded.')+`<div id="pilot-evidence-body"><p class="pilot-muted" role="status">Loading your private attempt history…</p></div>`;}
  function evidenceBody(attempts){const checked=attempts.filter(a=>a.mode==='check'&&a.result&&a.result.total>0),passed=checked.filter(a=>a.status==='completed'),independent=passed.filter(a=>!a.assistance?.hints&&!a.assistance?.answerViewed&&!a.assistance?.solutionLoaded&&!a.assistance?.externalHelp),competencies=[...new Set(checked.map(a=>byId.get(a.problem_id)?.competency).filter(Boolean))];return `<div class="evidence-stats">${[[attempts.length,'Saved attempts'],[new Set(passed.map(a=>a.problem_id)).size,'Tasks with full checks passed'],[independent.length,'Passes without recorded assistance'],[competencies.length,'Competencies attempted']].map(([value,label])=>`<div class="evidence-stat"><strong>${value}</strong><span>${label}</span></div>`).join('')}</div><p class="evidence-note">Figures use the latest 200 saved attempts; private export includes the full history. A passed check is evidence for that problem version and language. Assistance is recorded by the browser and self-report. These figures do not certify design quality, race freedom or interview readiness.</p>${transferBody(attempts)}<section class="pilot-panel"><h2>Competency evidence</h2><div class="evidence-scroll"><table class="evidence-table"><thead><tr><th>Competency</th><th>Observed checks</th><th>Explanation review</th></tr></thead><tbody>${competencies.length?competencies.map(name=>{const relevant=checked.filter(a=>byId.get(a.problem_id)?.competency===name),latest=relevant[0],baseline=[...relevant].reverse()[0];return `<tr><td>${esc(name.replaceAll('-',' '))}</td><td>First shown: ${baseline.result.passed}/${baseline.result.total}<br>Latest: ${latest.result.passed}/${latest.result.total}<small>Different tasks can have different difficulty and case counts; these are observations, not a normalised score.</small></td><td>${relevant.some(a=>a.explanation?.trim())?'Explanation recorded · self-review needed':'No explanation recorded'}</td></tr>`;}).join(''):'<tr><td colspan="3">Complete a full check to start collecting competency evidence.</td></tr>'}</tbody></table></div></section><section class="pilot-panel" style="margin-top:22px"><h2>Attempt history</h2><div class="evidence-scroll"><table class="evidence-table"><thead><tr><th>Exercise</th><th>Result</th><th>Assistance</th><th>Saved</th></tr></thead><tbody>${attempts.length?attempts.map(a=>`<tr><td><a href="#/lab?domain=Investment+Banking&language=java&question=${a.problem_id}">${esc(byId.get(a.problem_id)?.title||a.problem_id)}</a><small>${a.problem_version} · ${a.mode==='samples'?'sample run':'full check'}</small></td><td>${esc(a.status.replaceAll('_',' '))}${a.result?.total?`<small>${a.result.passed}/${a.result.total} checks</small>`:''}<button class="button quiet small" data-attempt-view="${a.id}">Inspect result</button></td><td>${esc(assistanceLabel(a.assistance||{}))}</td><td>${esc(new Date(a.created_at).toLocaleString())}<button class="button quiet small" data-attempt-restore="${a.id}">Restore source</button></td></tr>`).join(''):'<tr><td colspan="4">Your first sample run or full check will appear here.</td></tr>'}</tbody></table></div></section><div id="pilot-history-result"></div><div class="pilot-actions"><button class="button" data-pilot-summary>Download progress summary</button><a class="button" href="#/pilot">Data export & privacy →</a></div>`;}
  function transferBody(attempts){const checks=attempts.filter(a=>a.mode==='check'&&a.result?.total),seen=new Set(checks.map(a=>a.problem_id));for(const a of [...checks].reverse()){const p=byId.get(a.problem_id);if(!p)continue;const next=catalogue.find(x=>x.id!==p.id&&x.competency===p.competency&&!seen.has(x.id)&&!state.pilotAssistance?.[x.id]?.answerViewed);if(next){const due=dueDate(a.created_at.slice(0,10),7);return `<section class="pilot-transfer"><h3>${due<=dateOnly()?'A transfer check is available':'A fresh variation for later'}</h3><p>Revisit ${esc(p.competency.replaceAll('-',' '))} with “${esc(next.title)}” from ${due}. Try without requesting help and explain how the approach transfers. This recommendation uses the history and assistance known to this browser.</p>${link(next,due<=dateOnly()?'Try the variation':'Preview the variation')}</section>`;}}return '';}
  function anonymousDrafts(){try{return JSON.parse(localStorage.getItem('prepspace-workspace::anonymous')||'null');}catch{return null;}}
  function pilotPage(){if(!connection||connection.mode==='offline'&&state.pilotWorkspaceKind==='hosted')return heading('Free pilot, clear boundaries.','Connect to verify your account before exporting or changing private data.');return heading('Free pilot, clear boundaries.','Understand execution limits, privacy and what your preparation evidence means.')+`<div class="pilot-layout"><section><article class="pilot-panel"><span class="public-eyebrow">BANKING JAVA & SDET</span><h2>Practise without payment details</h2><p class="pilot-muted">The invited pilot is designed for 30 candidates. Reading is available without an account. Hosted execution and cloud history require sign-in and pilot membership.</p><div data-pilot-account><p class="pilot-muted">Checking your account and execution status…</p></div><div class="pilot-facts"><span>20 jobs per day</span><span>2 simultaneous jobs globally</span><span>128 KiB source limit</span><span>64 KiB output limit</span></div><p class="pilot-muted">Capacity may pause when the shared allocation is exhausted. Drafts, reading and downloads remain available. AI feedback is disabled until the expert benchmark and provider setup pass the release gate.</p></article><article class="pilot-panel" style="margin-top:22px"><h2>Your work stays private</h2><p class="pilot-muted">Source and explanations are private to your workspace. Processing location and sync availability are shown above. Avoid real employer data, credentials and confidential interview material.</p><p class="pilot-muted">Retained records include drafts, versions, attempts, test evidence, explanations, issue reports and your plan. Use export or deletion below. The pilot does not use source code to create public examples or train a model. There is no external AI call in this release.</p><label class="pilot-muted" style="display:block;margin-bottom:18px"><input type="checkbox" id="pilot-research-consent"> Contribute pseudonymous practice activity to pilot research. This excludes source code and explanations. Withdrawing deletes these research events.</label>${anonymousDrafts()?'<p class="pilot-muted">Anonymous practice drafts are saved separately on this device. Import them only if they are yours.</p><button class="button" data-pilot-import-anonymous>Import my anonymous browser drafts</button>':''}<div class="pilot-account-actions"><button class="button" data-pilot-export>Download private data</button><button class="button danger" data-pilot-delete>Delete my preparation data</button></div><div id="pilot-delete-confirm" hidden class="pilot-notice"><p>Delete this workspace's saved server records and all PrepSpace notes, drafts and progress in this browser? This cannot be undone. Download your data first if you need a copy.</p><button class="button danger" data-pilot-confirm-delete>Delete server and browser data</button> <button class="button" data-pilot-cancel-delete>Keep my data</button></div></article><article class="pilot-panel" style="margin-top:22px"><h2>Content quality and corrections</h2><p class="pilot-muted">All ${catalogue.length} pilot references have automated verification metadata. Practitioner review is pending. Report an issue directly from an exercise; reports are reviewed manually, with no guaranteed response time during the pilot.</p><p class="pilot-muted">Problems are original preparation scenarios. They are not represented as verified prompts used by a particular employer.</p><a class="button" href="#/pilot-research">Read the product research →</a></article></section><aside class="pilot-panel"><span class="public-eyebrow">WHAT IS MEASURED</span><h2>Evidence with context</h2><ul class="lab-criteria">${['Documented functional checks','Seeded fault detection for test-design tasks','Recorded hints and answer use','Your own explanation and self-review','A later variation on the competency'].map(x=>`<li><span class="criteria-tick">✓</span>${x}</li>`).join('')}</ul><p class="pilot-muted">There is no overall interview-readiness percentage or guarantee of hiring success. Actual interview outcomes are optional research, collected separately with consent.</p></aside></div>`;}
  function research(){return heading('Why we are building PrepSpace.','A focused banking preparation pilot, informed by product research and candidate feedback.')+`<section class="pilot-panel"><h2>Research is a starting point</h2><p class="pilot-muted">The November 2026 landscape review covered 20 representative coding, assessment and preparation platforms. AI mocks, roadmaps, project exercises and specialist tracks already exist. Our pilot tests whether reviewed banking Java/SDET tasks and clear evidence improve preparation.</p><p class="pilot-muted">Public reviews are self-selected and employer settings affect assessment experiences. Complaints are research signals, not prevalence estimates or claims that a competitor currently lacks a feature.</p><h3>Useful sources</h3><ul class="pilot-feedback"><li><a href="https://leetcode.com/subscribe/" target="_blank" rel="noopener">LeetCode: current premium capabilities</a></li><li><a href="https://www.hackerrank.com/mock-interviews" target="_blank" rel="noopener">HackerRank: AI mock formats</a></li><li><a href="https://coderpad.io/resources/docs/screen/tests/projects/" target="_blank" rel="noopener">CoderPad: project assessments</a></li><li><a href="https://www.trustpilot.com/review/hackerrank.com" target="_blank" rel="noopener">Candidate feedback: requirements, reliability and practice formats</a></li><li><a href="https://www.g2.com/products/coderpad/reviews" target="_blank" rel="noopener">CoderPad user feedback: collaboration and editor experience</a></li><li><a href="https://www.trustpilot.com/review/www.educative.io" target="_blank" rel="noopener">Educative feedback: content, value and subscriptions</a></li></ul><h3>Validation still to complete</h3><p class="pilot-muted">Twelve candidate interviews, four practitioner interviews, external content reviews and two pilot cohorts remain research work. No participants, testimonials or measured learning improvements have been invented. Wider domains expand only after quality, demand and operating capacity are demonstrated.</p></section>`;}
  function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function hydrateDrafts(p){try{const result=await api('drafts'),remote=result.drafts.find(x=>x.problem_id===p.id);if(!remote||mounted!==p.id)return;const d=draft(p);if(!d.updatedAt){d.files=remote.files;d.revision=remote.revision;d.updatedAt=remote.updated_at;persist();PrepEditor.setCode(d.files[d.activeFile]||d.files['Main.java']);}else if(JSON.stringify(d.files)===JSON.stringify(remote.files)){d.revision=remote.revision;persist();saveLabel(d.localSaveOk===false?'Saved to the service · browser storage unavailable':connection?.mode==='hosted'?'Saved in this browser and your account':'Saved in this browser and this Mac');}else if(d.revision!==remote.revision){d.conflict={revision:remote.revision,files:remote.files};persist();paintConflict(p);}else syncDraft(p);}catch{}}
  async function mount(){const waiting=!connection;mounted=route().path==='lab'&&problem(labQuestion().item)?labQuestion().item.id:null;const p=mounted?byId.get(mounted):null;if(p&&document.getElementById('run-code')){document.getElementById('run-code').textContent='▶ Run samples';document.getElementById('load-demo').hidden=true;document.getElementById('restore-code').hidden=true;document.getElementById('program-stdin').closest('.stdin-panel').hidden=true;const note=document.querySelector('.execution-note');if(note)note.textContent='Runs the problem’s sample inputs. Use Check full contract for all documented checks. Ctrl/Cmd + Enter runs samples.';if(lastResults.has(p.id))paintRun(lastResults.get(p.id));else if(state.pilotResults[p.id])api('jobs/'+state.pilotResults[p.id]).then(a=>{if(mounted===p.id)paintRun(a);}).catch(()=>{});if(draft(p).conflict)paintConflict(p);hydrateDrafts(p);}
    await health();if(waiting){render();return;}paintConnection();const consent=document.getElementById('pilot-research-consent');if(consent)consent.checked=!!connection.telemetry;
    const account=document.querySelector('[data-pilot-account]');if(account){account.innerHTML=connection.mode==='local'?`<div class="pilot-notice">Local workspace · code and saved records stay on this Mac. Cloud accounts and cross-device sync require the hosted pilot backend.</div><p class="pilot-muted">${esc(connection.processingRegion||'')}<br>${connection.quota.remaining} daily jobs remaining.</p>`:connection.mode==='hosted'?`<p class="pilot-muted">${connection.member?'Signed in · pilot member':connection.signedIn?'Signed in · pilot invitation required':'Browsing without an account'}<br>Execution: ${connection.executionReady?'available':'not enabled'}<br>Processing region: ${esc(connection.processingRegion||'not configured')}</p>${!connection.signedIn?'<a class="button primary" target="_top" href="/signin-with-chatgpt?return_to=%2F%23%2Fpilot">Sign in with ChatGPT →</a>':!connection.member?'<form id="pilot-invite-form"><label class="pilot-field">PILOT INVITATION CODE<input id="pilot-invite-code" required autocomplete="off"></label><button class="button primary" style="margin-top:12px">Join invited pilot</button><p class="pilot-muted" id="pilot-invite-status"></p></form>':'<a class="button" target="_top" href="/signout-with-chatgpt?return_to=%2F">Sign out</a>'}`:`<div class="pilot-notice">${esc(connection.error||'The hosted preparation service is not configured. Browser drafts and reading remain available.')}</div>`;}
    if(document.getElementById('pilot-evidence-body')){try{const {attempts}=await api('attempts');if(document.getElementById('pilot-evidence-body')){document.getElementById('pilot-evidence-body').innerHTML=evidenceBody(attempts);state.pilotSummaryAttempts=attempts.map(a=>({id:a.id,problemId:a.problem_id,status:a.status,mode:a.mode,assistance:a.assistance,createdAt:a.created_at,result:a.result?{passed:a.result.passed,total:a.result.total}:null}));persist();}}catch(error){const el=document.getElementById('pilot-evidence-body');if(el)el.innerHTML=`<div class="pilot-notice">${esc(error.message)}</div><a class="button" href="#/pilot">Account & execution status →</a>`;}}
    if(['prepare','plan'].includes(route().path)){try{const saved=await api('plan');if(saved.document&&saved.revision>(state.pilotPlanRevision||0)){if(state.pilotPlanDirty){state.pilotPlanConflict=saved;persist();const banner=document.getElementById('pilot-plan-conflict');if(banner)banner.hidden=false;}else {state.pilotPlan=saved.document;state.pilotPlanRevision=saved.revision;persist();render();}}}catch{}}
  }
  async function savePlan(){state.pilotPlanDirty=true;persist();try{const saved=await api('plan',{method:'POST',body:JSON.stringify({document:state.pilotPlan,revision:state.pilotPlanRevision||0})});state.pilotPlanRevision=saved.revision;state.pilotPlanDirty=false;state.pilotPlanConflict=null;persist();const el=document.getElementById('pilot-plan-save');if(el)el.textContent=connection?.mode==='hosted'?'Saved to your account':'Saved in this browser and this Mac';}catch(error){if(error.status===409){const remote=await api('plan').catch(()=>null);if(remote){state.pilotPlanConflict=remote;persist();const banner=document.getElementById('pilot-plan-conflict');if(banner)banner.hidden=false;}}const el=document.getElementById('pilot-plan-save');if(el)el.textContent=error.status===409?'Saved in this browser · server has a newer plan; export or reload before syncing.':'Saved in this browser · server sync unavailable';}}
  document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;const p=mounted?byId.get(mounted):null;
    if(b.matches('[data-legacy-draft]')&&p){snapshot(p);draft(p).files['Main.java']=state.drafts[p.id+'::java']||state.drafts[p.id];draft(p).activeFile='Main.java';draft(p).legacyHandled=true;saveDraft(p);render();}
    if(b.matches('[data-pilot-check]'))execute('check');
    if(b.matches('[data-pilot-file]')&&p){saveDraft(p,PrepEditor.getValue());draft(p).activeFile=b.dataset.pilotFile;PrepEditor.setCode(draft(p).files[draft(p).activeFile]);document.querySelectorAll('[data-pilot-file]').forEach(el=>el.setAttribute('aria-selected',String(el===b)));persist();}
    if(b.matches('[data-pilot-next-hint]')&&p){const list=document.querySelector('[data-pilot-hint-list]'),n=list.children.length;if(n<p.hints.length){const li=document.createElement('li');li.textContent=p.hints[n];list.append(li);assistance(p).hints=Math.max(assistance(p).hints,n+1);markAssistance(p);}document.querySelector('[data-pilot-hint-count]').textContent=list.children.length+' of '+p.hints.length;b.textContent=list.children.length===p.hints.length?'All hints shown':'Next hint';b.disabled=list.children.length===p.hints.length;}
    if(b.matches('[data-pilot-answer]')&&p)reveal(p,b);
    if(b.matches('[data-pilot-load-answer]')&&p&&answerCache.has(p.id)){snapshot(p);draft(p).files={...answerCache.get(p.id).files};draft(p).activeFile='Main.java';assistance(p).solutionLoaded=true;saveDraft(p);render();toast('Worked project loaded. Your previous project is available through Restore previous project.');}
    if(b.matches('[data-pilot-restore]')&&p){const previous=draft(p).snapshots?.shift();if(!previous){toast('No earlier project snapshot is available.');return;}const current={files:{...files(p,PrepEditor.getValue())},at:new Date().toISOString()};draft(p).files={...previous.files};draft(p).snapshots.push(current);saveDraft(p);render();}
    if(b.matches('[data-pilot-download]')&&p){saveDraft(p,PrepEditor.getValue());const response=await fetch('/api/pilot/project-download',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({problemId:p.id,files:files(p)})});if(response.ok){const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=p.id+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else download(p.id+'.json',JSON.stringify({problemId:p.id,version:p.version,files:files(p)},null,2));}
    if(b.matches('[data-conflict]')&&p){const d=draft(p),conflict=d.conflict;if(!conflict)return;snapshot(p);if(b.dataset.conflict==='server')d.files={...conflict.files};else d.snapshots.unshift({files:{...conflict.files},at:new Date().toISOString()});d.revision=conflict.revision;d.conflict=null;saveDraft(p);render();}
    if(b.matches('[data-plan-conflict]')){const conflict=state.pilotPlanConflict;if(!conflict)return;state.pilotPlanBackup=state.pilotPlan;if(b.dataset.planConflict==='server'){state.pilotPlan=conflict.document;state.pilotPlanDirty=false;}state.pilotPlanRevision=conflict.revision;state.pilotPlanConflict=null;persist();render();if(b.dataset.planConflict==='local')savePlan();}
    if(b.matches('[data-pilot-day]')){const n=Number(b.dataset.pilotDay),plan=state.pilotPlan;plan.completed=plan.completed.includes(n)?plan.completed.filter(x=>x!==n):[...plan.completed,n];if(plan.completed.includes(n))api('events',{method:'POST',body:JSON.stringify({kind:'session_completed'})}).catch(()=>{});persist();render();savePlan();}
    if(b.matches('[data-attempt-view]')){try{const attempt=await api('jobs/'+b.dataset.attemptView);document.getElementById('pilot-history-result').innerHTML=`<section class="pilot-results">${resultHtml(attempt)}${attempt.explanation?'<h4>Saved explanation</h4><p class="pilot-muted">'+esc(attempt.explanation)+'</p>':''}</section>`;}catch(error){toast(error.message);}}
    if(b.matches('[data-attempt-restore]')){try{const a=await api('jobs/'+b.dataset.attemptRestore),p=byId.get(a.problem_id);if(!a.files)throw new Error('Source restoration is unavailable for this historical attempt.');snapshot(p);draft(p).files={...a.files};draft(p).explanation=a.explanation;saveDraft(p);go('lab?round=coding&domain=Investment+Banking&language=java&question='+p.id);}catch(error){toast(error.message);}}
    if(b.matches('[data-pilot-import-anonymous]')){const old=anonymousDrafts();if(!old)return;for(const [id,record] of Object.entries(old.pilotDrafts||{})){if(!byId.has(id))continue;if(state.pilotDrafts[id])state.pilotDrafts[id].snapshots.unshift({files:record.files,at:new Date().toISOString()});else state.pilotDrafts[id]={...record,revision:0,dirty:true};const a=old.pilotAssistance?.[id],current=assistance(byId.get(id));if(a){current.hints=Math.max(current.hints,a.hints||0);current.answerViewed||=a.answerViewed;current.solutionLoaded||=a.solutionLoaded;current.externalHelp||=a.externalHelp;}}persist();toast('Anonymous drafts imported. Existing projects were preserved; imported alternatives are available through Restore previous project.');}
    if(b.matches('[data-pilot-export]')){try{const response=await fetch('/api/pilot/export',{headers:state.pilotWorkspaceKey?{'X-PrepSpace-Workspace':state.pilotWorkspaceKey}:{}});if(!response.ok)throw new Error('Server export unavailable. Reconnect and verify your workspace before exporting.');const remote=await response.blob();download('prepspace-private-data.ndjson',new Blob([remote,'\n',JSON.stringify({table:'browser',row:state}),'\n'],{type:'application/x-ndjson'}),'application/x-ndjson');}catch(error){toast(error.message);}}
    if(b.matches('[data-pilot-summary]'))download('prepspace-progress-summary.json',JSON.stringify({generatedAt:new Date().toISOString(),scope:'Candidate-selected progress summary; no source code or explanation text',limitations:'Problem-specific functional evidence; no hiring prediction. Assistance is self-reported.',attempts:state.pilotSummaryAttempts||[]},null,2));
    if(b.matches('[data-pilot-delete]'))document.getElementById('pilot-delete-confirm').hidden=false;
    if(b.matches('[data-pilot-cancel-delete]'))document.getElementById('pilot-delete-confirm').hidden=true;
    if(b.matches('[data-pilot-confirm-delete]')){b.disabled=true;try{await api('account',{method:'DELETE',body:'{}'});for(const key of Object.keys(localStorage))if(key.startsWith('prepspace')||key==='tradecraft-v1')localStorage.removeItem(key);location.reload();}catch(error){toast(error.message);b.disabled=false;}}
  });
  window.addEventListener('online',()=>{health(true).then(()=>{paintConnection();if(mounted)syncDraft(byId.get(mounted));});});
  document.addEventListener('input',event=>{const p=mounted?byId.get(mounted):null;if(p&&event.target.id==='lab-answer')saveDraft(p,event.target.value);if(p&&event.target.id==='pilot-explanation'){draft(p).explanation=event.target.value;persist();}});
  document.addEventListener('change',async event=>{if(event.target.id==='pilot-research-consent'){try{await api('consent',{method:'POST',body:JSON.stringify({enabled:event.target.checked})});connection.telemetry=event.target.checked;toast(event.target.checked?'Research activity sharing enabled. Source code and explanations are excluded.':'Research sharing withdrawn and recorded research events deleted.');}catch(error){event.target.checked=!event.target.checked;toast(error.message);}}if(event.target.id==='pilot-format'){const r=route();if(event.target.value==='all')r.query.delete('format');else r.query.set('format',event.target.value);r.query.delete('question');go('lab?'+r.query.toString());}if(event.target.id==='pilot-external-help'&&mounted){assistance(byId.get(mounted)).externalHelp=event.target.checked;markAssistance(byId.get(mounted));}});
  document.addEventListener('submit',async event=>{if(event.target.id==='pilot-plan-form'){event.preventDefault();state.pilotPlan=createPlan(document.getElementById('pilot-plan-track').value,Number(document.getElementById('pilot-plan-days').value),document.getElementById('pilot-plan-format').value);history.replaceState(null,'','#/prepare?track='+state.pilotPlan.track);persist();render();savePlan();}if(event.target.id==='pilot-report-form'&&mounted){event.preventDefault();try{const result=await api('reports',{method:'POST',body:JSON.stringify({problemId:mounted,kind:document.getElementById('pilot-report-kind').value,body:document.getElementById('pilot-report-body').value})});document.getElementById('pilot-report-status').textContent='Issue recorded: '+result.id+'. Reports are reviewed manually.';}catch(error){document.getElementById('pilot-report-status').textContent=error.message;}}if(event.target.id==='pilot-invite-form'){event.preventDefault();try{await api('join',{method:'POST',body:JSON.stringify({code:document.getElementById('pilot-invite-code').value})});await health(true);render();}catch(error){document.getElementById('pilot-invite-status').textContent=error.message;}}});
  return {install,mount,prompt,problem,execute,stop,files,createPlan,resultHtml,evidenceBody,workspaceReady:()=>!!connection&&!(connection.mode==='offline'&&state.pilotWorkspaceKind==='hosted'),learningAttempts:async()=>{await health(true);if(!connection||connection.mode==='offline')throw new Error('Execution history is unavailable.');const result=await api('attempts');return result.attempts||[];},views:{prepare,evidence,pilot:pilotPage,'pilot-research':research},
    prepareBase(items){const existing=new Set(items.map(i=>i.id));return [...items,...catalogue.filter(p=>!existing.has(p.id)).map(p=>({id:p.id,type:'problem',language:'java',title:p.title,category:'Banking pilot',domain:'Investment Banking',rounds:['coding'],roles:['all'],solved:true,pilotOnly:true,text:p.description}))];},
    materialize(item,language){const p=language==='java'?byId.get(item.id):null;return p?{...item,title:p.title,question:prompt(p),html:prompt(p),solved:true,pilotSpec:p,starter:p.starter['Main.java'],code:null}:item;},
    editorChange(item,code){const p=problem(item);if(p&&route().path==='lab')saveDraft(p,code);},
    beforeRender(){stop();mounted=null;},isAssessed(item){return !!problem(item)&&route().path==='lab';}
  };
})();
